sources.adapter.cod:
import "/ws/EvtWorks/cod-project/tests/cod/language/reusable-pool.cod" Pool;
using "/ws/EvtWorks/cod-project/tests/cod/language/pool-interface.cod" SlotStore;
data Pool <: SlotStore;
using units "/ws/EvtWorks/cod-project/tests/cod/language/reusable-pool.cod" {Slot};
using "/ws/EvtWorks/cod-project/tests/cod/language/reusable-pool.cod" read;
import "operations.cod" lookup;
function lookup(pool::Pool, slot::Slot)::i64 { read(pool, slot) }
function adapter_total(pool::SlotStore, count::u32)::i64 { fold (i in 0u32 .. count, sum = 0) { sum + lookup(pool, Slot(i)) } }

sources.direct.cod:
using symbol "std:io" @print;
using "adapter.cod" Pool;
using "adapter.cod" lookup;
using "adapter.cod" adapter_total;
using "algorithm.cod" total;
using units "/ws/EvtWorks/cod-project/tests/cod/language/reusable-pool.cod" {Slot};
using "/ws/EvtWorks/cod-project/tests/cod/language/reusable-pool.cod" create;
using "/ws/EvtWorks/cod-project/tests/cod/language/reusable-pool.cod" acquire;
symbol @arena::region;
effect @arena <- region(4096u64);
{
  let pool = create(@arena, 2u32);
  acquire(pool, 7);
  acquire(pool, 11);
  behave @print(lookup(pool, Slot(0u32)) + lookup(pool, Slot(1u32)));
  behave @print(adapter_total(pool, 2u32));
};

